function updateRoomScale(){const wrap=seatEl('#seatingPrintArea');if(!wrap||wrap.clientWidth<1)return;seatingBoard.style.zoom='';seatingGrid.style.zoom='';const naturalWidth=seatingState.layoutMode==='custom'?seatingState.roomWidth:Math.max(560,seatingGrid.scrollWidth),naturalHeight=(seatingState.layoutMode==='custom'?seatingState.roomHeight:seatingGrid.scrollHeight)+100,fit=Math.max(.25,Math.min(1.6,(wrap.clientWidth-42)/naturalWidth,(wrap.clientHeight-42)/naturalHeight));currentRoomScale=Math.max(.25,Math.min(2.5,manualRoomScale??fit));seatingBoard.style.zoom=String(currentRoomScale);const label=seatEl('#seatingZoomLabel');if(label)label.textContent=`${Math.round(currentRoomScale*100)}%`}
function fitSeatingRoom(){manualRoomScale=null;updateRoomScale()}
