function shuffleChart(){const open=seatingState.seats.map((_,i)=>i).filter(i=>!seatingState.locked[i]),names=open.map(i=>seatingState.seats[i]).filter(Boolean),arranged=arrangement(names,open.length);open.forEach((i,p)=>seatingState.seats[i]=arranged[p]||null);renderSeatingChart();queueSave()}
function createGroups(){const count=Number(seatEl('#seatingGroupCount').value)||2,names=shuffled(rosterNames()),groups=Array.from({length:count},()=>[]);names.forEach((name,i)=>groups[i%count].push(name));seatEl('#seatingGroupResults').innerHTML=groups.map((group,i)=>`<section><strong>Group ${i+1}</strong><p>${group.join('<br>')||'—'}</p></section>`).join('')}
function importRoster(file){const reader=new FileReader();reader.onload=()=>{let rows=String(reader.result||'').split(/\r?\n/).map(row=>row.split(',')[0].replace(/^\s*["']|["']\s*$/g,'').trim()).filter(Boolean);if(/^(student|name|student name)$/i.test(rows[0]||''))rows.shift();seatingRoster.value=rows.slice(0,100).join('\n');showToast(`${Math.min(rows.length,100)} students imported`);queueSave()};reader.readAsText(file)}
