function setStorage(mode){seatingStorageMode=mode;localStorage.setItem('glnSeatingStorageMode',mode);seatingLocalMode.classList.toggle('active',mode==='local');seatingGoogleMode.classList.toggle('active',mode==='google');const signed=Boolean(currentUser&&!currentUser.isAnonymous);seatingGoogleSignIn.hidden=mode!=='google'||signed;if(mode==='local')saveLocal();else if(signed)loadCloud();else initializeAccount()}
async function initializeAccount(){try{await initRaceFirebase();if(currentUser&&!currentUser.isAnonymous){seatingGoogleSignIn.hidden=true;await loadCloud()}else{seatingGoogleSignIn.hidden=false;seatingStorageStatus.textContent='Sign in to sync all classes across devices'}}catch{seatingGoogleSignIn.hidden=false;seatingStorageStatus.textContent='Google sync is not configured yet.'}}
async function signInGoogle(){seatingGoogleSignIn.disabled=true;try{await initRaceFirebase();const provider=new fb.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});const credential=await fb.signInWithPopup(auth,provider);currentUser=credential.user;seatingGoogleSignIn.hidden=true;await loadCloud()}catch{seatingStorageStatus.textContent='Google sign-in was not completed.'}finally{seatingGoogleSignIn.disabled=false}}
async function loadCloud(){if(!currentUser||currentUser.isAnonymous)return;try{const snapshot=await fb.get(fb.ref(db,`seatingCharts/${currentUser.uid}`));if(snapshot.exists()){const data=snapshot.val();if(Array.isArray(data.classes)&&data.classes.length){seatingClasses=data.classes.map(normalize);activeClassId=data.activeClassId||seatingClasses[0].id;applyState(seatingClasses.find(c=>c.id===activeClassId)||seatingClasses[0])}}else await saveCloud();seatingStorageStatus.textContent=`Synced with ${currentUser.email||'Google account'}`;seatingStorageStatus.classList.add('synced')}catch{seatingStorageStatus.textContent='Could not load the cloud copy.'}}
function selectedDeskIndexes(){return seatingState.deskLayout.map((desk,index)=>selectedDesks.has(desk.id)?index:-1).filter(index=>index>=0)}
function addDesk(){pushDeskHistory();if(seatingState.layoutMode!=='custom')gridToCustom();const index=seatingState.deskLayout.length,spot=findOpenDeskSpot(98,68);if(!spot){deskUndo.pop();showToast('No open space for another desk');return}const desk={id:`desk-${Date.now()}-${index}`,...spot,w:98,h:68,rotation:0};seatingState.deskLayout.push(desk);seatingState.seats.push(null);seatingState.locked.push(false);selectedDesks=new Set([desk.id]);layoutEditing=true;renderSeatingChart();queueSave()}
function deleteSelectedDesks(){const indexes=selectedDeskIndexes().sort((a,b)=>b-a);if(!indexes.length){showToast('Select a desk first');return}pushDeskHistory();indexes.forEach(index=>{seatingState.deskLayout.splice(index,1);seatingState.seats.splice(index,1);seatingState.locked.splice(index,1)});selectedDesks.clear();renderSeatingChart();queueSave()}
function duplicateSelectedDesk(){const index=selectedDeskIndexes()[0];if(index===undefined){showToast('Select a desk first');return}const source=seatingState.deskLayout[index],spot=findOpenDeskSpot(source.w,source.h,source.x+20,source.y+20,new Set(),source.rotation||0);if(!spot){showToast('No open space to duplicate this desk');return}pushDeskHistory();const desk={...source,...spot,id:`desk-${Date.now()}`};seatingState.deskLayout.push(desk);seatingState.seats.push(null);seatingState.locked.push(false);selectedDesks=new Set([desk.id]);renderSeatingChart();queueSave()}
function rotateSelected(){const indexes=selectedDeskIndexes();if(!indexes.length){showToast('Select a desk first');return}const changes=new Map(indexes.map(index=>{const desk=seatingState.deskLayout[index];return[desk.id,{...desk,rotation:((desk.rotation||0)+15)%360}]}));if(!validDeskChanges(changes)){flashDeskCollision();showToast('Not enough space to rotate these desks');return}pushDeskHistory();applyDeskChanges(changes);renderSeatingChart();queueSave()}
function applySelectedSizeToAll(){const index=selectedDeskIndexes()[0];if(selectedDesks.size!==1||index===undefined){showToast('Select one desk first');return}const source=seatingState.deskLayout[index];pushDeskHistory();seatingState.deskLayout.forEach(desk=>{desk.w=source.w;desk.h=source.h});seatingState.roomWidth=Math.max(seatingState.roomWidth,...seatingState.deskLayout.map(desk=>desk.x+desk.w+20));seatingState.roomHeight=Math.max(seatingState.roomHeight,...seatingState.deskLayout.map(desk=>desk.y+desk.h+20));seatEl('#roomWidth').value=Math.round(seatingState.roomWidth);seatEl('#roomHeight').value=Math.round(seatingState.roomHeight);renderSeatingChart();queueSave();showToast('All desks now match the selected desk')}
function toggleLayoutEditor(){if(seatingState.layoutMode!=='custom'){pushDeskHistory();gridToCustom();layoutEditing=true}else layoutEditing=!layoutEditing;selectedDesks.clear();renderSeatingChart();queueSave()}
function undoDeskEdit(){if(!deskUndo.length)return;deskRedo.push(deskSnapshot());restoreDeskSnapshot(deskUndo.pop())}
function redoDeskEdit(){if(!deskRedo.length)return;deskUndo.push(deskSnapshot());restoreDeskSnapshot(deskRedo.pop())}
function uniqueClassName(base){let name=base,number=2;while(seatingClasses.some(item=>item.className===name))name=`${base} ${number++}`;return name}
function duplicateCurrentClass(){saveLocal();const copy=normalize(JSON.parse(JSON.stringify(seatingState)));copy.id=`class-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;copy.className=uniqueClassName(`${seatingState.className} Copy`);copy.deskLayout=copy.deskLayout.map((desk,index)=>({...desk,id:`desk-${Date.now()}-${index}`}));copy.updatedAt=Date.now();seatingClasses.push(copy);applyState(copy);queueSave();showToast('Class duplicated')}
function useAnotherClassLayout(){const source=seatingClasses.find(item=>item.id===seatEl('#seatingLayoutSource').value);if(!source){showToast('Choose another class first');return}capture();pushDeskHistory();seatingState.layoutMode='custom';seatingState.flipped=source.flipped;seatingState.roomWidth=source.roomWidth;seatingState.roomHeight=source.roomHeight;seatingState.roomPreset=source.roomPreset;seatEl('#roomWidth').value=source.roomWidth;seatEl('#roomHeight').value=source.roomHeight;seatEl('#roomPreset').value=source.roomPreset;seatingState.deskLayout=source.deskLayout.map((desk,index)=>({...desk,id:`desk-${Date.now()}-${index}`}));const count=seatingState.deskLayout.length;seatingState.seats=seatingState.roster.slice(0,count);while(seatingState.seats.length<count)seatingState.seats.push(null);seatingState.locked=Array(count).fill(false);layoutEditing=false;selectedDesks.clear();renderSeatingChart();queueSave();showToast(`Layout copied from ${source.className}`)}
