function setRoomPreset(){const preset=seatEl('#roomPreset').value;if(roomPresets[preset]){pushDeskHistory();[seatingState.roomWidth,seatingState.roomHeight]=roomPresets[preset];const neededWidth=Math.max(500,...seatingState.deskLayout.map(d=>d.x+d.w+20)),neededHeight=Math.max(360,...seatingState.deskLayout.map(d=>d.y+d.h+20));seatingState.roomWidth=Math.max(seatingState.roomWidth,neededWidth);seatingState.roomHeight=Math.max(seatingState.roomHeight,neededHeight);seatEl('#roomWidth').value=seatingState.roomWidth;seatEl('#roomHeight').value=seatingState.roomHeight;renderSeatingChart();queueSave()}}
function updateRoomInputs(){pushDeskHistory();const neededWidth=Math.max(500,...seatingState.deskLayout.map(d=>d.x+d.w+20)),neededHeight=Math.max(360,...seatingState.deskLayout.map(d=>d.y+d.h+20));seatingState.roomWidth=Math.max(neededWidth,Math.min(2000,Number(seatEl('#roomWidth').value)||760));seatingState.roomHeight=Math.max(neededHeight,Math.min(1400,Number(seatEl('#roomHeight').value)||520));seatingState.roomPreset='custom';seatEl('#roomPreset').value='custom';seatEl('#roomWidth').value=seatingState.roomWidth;seatEl('#roomHeight').value=seatingState.roomHeight;renderSeatingChart();queueSave()}
function beginRoomResize(event){if(!layoutEditing||seatingState.layoutMode!=='custom')return;event.preventDefault();pushDeskHistory();const sx=event.clientX,sy=event.clientY,ow=seatingState.roomWidth,oh=seatingState.roomHeight,neededWidth=Math.max(500,...seatingState.deskLayout.map(d=>d.x+d.w+20)),neededHeight=Math.max(360,...seatingState.deskLayout.map(d=>d.y+d.h+20));const move=e=>{seatingState.roomWidth=Math.max(neededWidth,Math.min(2000,ow+(e.clientX-sx)/currentRoomScale));seatingState.roomHeight=Math.max(neededHeight,Math.min(1400,oh+(e.clientY-sy)/currentRoomScale));seatingState.roomPreset='custom';seatEl('#roomPreset').value='custom';seatEl('#roomWidth').value=Math.round(seatingState.roomWidth);seatEl('#roomHeight').value=Math.round(seatingState.roomHeight);renderSeatingChart()};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);queueSave()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)}
const shortcutRows=[['Undo','⌘/Ctrl Z'],['Redo','⌘/Ctrl Shift Z'],['Select all desks','⌘/Ctrl A'],['Copy desks','⌘/Ctrl C'],['Paste desks','⌘/Ctrl V'],['Duplicate desks','⌘/Ctrl D'],['Delete desks','Delete/Backspace'],['Move 1 pixel','Arrow keys'],['Move 10 pixels','Shift + Arrow'],['Rotate desks','R'],['Lock or unlock','L'],['Edit layout','E'],['Clear selection','Esc'],['Save','⌘/Ctrl S'],['Disable smart snap temporarily','Hold Option/Alt']];
function setupShortcutDialog(){seatEl('#deskShortcutList').innerHTML=shortcutRows.map(([action,key])=>`<div><span>${action}</span><kbd>${key}</kbd></div>`).join('')}
function seatingShortcut(event){if(seatEl('#seatingPanel').hidden)return;const target=event.target;if(/INPUT|TEXTAREA|SELECT/.test(target.tagName)||target.isContentEditable)return;const mod=event.metaKey||event.ctrlKey,key=event.key.toLowerCase();if(key==='f'&&!mod){event.preventDefault();fitSeatingRoom();return}if(key==='e'&&!mod){event.preventDefault();toggleLayoutEditor();return}if(key==='escape'){seatEl('#seatingPanel').classList.remove('classes-open','inspector-open');selectedDesks.clear();refreshDeskSelection();return}if(!layoutEditing)return;if(mod&&key==='z'){event.preventDefault();event.shiftKey?redoDeskEdit():undoDeskEdit();return}if((event.ctrlKey&&key==='y')){event.preventDefault();redoDeskEdit();return}if(mod&&key==='a'){event.preventDefault();selectedDesks=new Set(seatingState.deskLayout.map(d=>d.id));refreshDeskSelection();return}if(mod&&key==='c'){event.preventDefault();copySelectedDesks();return}if(mod&&key==='v'){event.preventDefault();pasteDesks();return}if(mod&&key==='d'){event.preventDefault();duplicateSelectedDesk();return}if(mod&&key==='s'){event.preventDefault();queueSave();showToast('Layout saved');return}if(key==='delete'||key==='backspace'){event.preventDefault();deleteSelectedDesks();return}if(key==='r'){event.preventDefault();rotateSelected();return}if(key==='l'){event.preventDefault();const indexes=selectedDeskIndexes();if(indexes.length){pushDeskHistory();const lock=!indexes.every(i=>seatingState.locked[i]);indexes.forEach(i=>seatingState.locked[i]=lock);renderSeatingChart();queueSave()}return}const arrows={arrowleft:[-1,0],arrowright:[1,0],arrowup:[0,-1],arrowdown:[0,1]};if(arrows[key]){event.preventDefault();const amount=event.shiftKey?10:1;moveSelectedByKeyboard(arrows[key][0]*amount,arrows[key][1]*amount)}}
function setupDeskTooltips(){const toggle=seatEl('#deskTooltips'),tooltip=seatEl('#deskTooltip'),mac=/Mac|iPhone|iPad/.test(navigator.platform);toggle.checked=localStorage.getItem('glnDeskTooltips')!=='off';let timer;document.addEventListener('pointerover',event=>{const target=event.target.closest('[data-tip]');if(!target||!toggle.checked)return;clearTimeout(timer);timer=setTimeout(()=>{const [text,key]=target.dataset.tip.split('|');tooltip.innerHTML=`<strong>${text}</strong>${key?`<kbd>${key.replace('mod',mac?'⌘':'Ctrl')}</kbd>`:''}`;tooltip.hidden=false;const box=target.getBoundingClientRect();tooltip.style.left=`${Math.min(window.innerWidth-240,Math.max(8,box.left))}px`;tooltip.style.top=`${Math.min(window.innerHeight-70,box.bottom+8)}px`},350)});document.addEventListener('pointerout',event=>{if(event.target.closest('[data-tip]')){clearTimeout(timer);tooltip.hidden=true}});toggle.onchange=()=>{localStorage.setItem('glnDeskTooltips',toggle.checked?'on':'off');tooltip.hidden=true}}
function setupSeatingWorkspace(){const inspector=seatEl('#seatingInspector'),left=seatEl('#seatingClassPanel');left.querySelectorAll('.inspector-control,.layout-editor,.seating-rules,.seating-groups,.seating-help').forEach(node=>inspector.append(node));const panel=seatEl('#seatingPanel'),syncVisibility=()=>{const active=!panel.hidden;document.body.classList.toggle('seating-workspace-active',active);if(active)requestAnimationFrame(fitSeatingRoom)};new MutationObserver(syncVisibility).observe(panel,{attributes:true,attributeFilter:['hidden']});syncVisibility();seatEl('#toggleClassPanel').onclick=()=>panel.classList.toggle('classes-open');seatEl('#closeClassPanel').onclick=()=>panel.classList.remove('classes-open');seatEl('#toggleInspectorPanel').onclick=()=>panel.classList.toggle('inspector-open');seatEl('#closeInspectorPanel').onclick=()=>panel.classList.remove('inspector-open');seatEl('#toggleSeatingPanels').onclick=()=>{panel.classList.toggle('view-only');seatEl('#toggleSeatingPanels').textContent=panel.classList.contains('view-only')?'Show panels':'View only';requestAnimationFrame(fitSeatingRoom)};seatEl('#fitSeatingRoom').onclick=fitSeatingRoom;seatEl('#seatingZoomOut').onclick=()=>changeSeatingZoom(-.1);seatEl('#seatingZoomIn').onclick=()=>changeSeatingZoom(.1);seatEl('#quickBuildSeating').onclick=()=>seatEl('#buildSeating').click();seatEl('#quickShuffleSeating').onclick=()=>seatEl('#shuffleSeating').click();seatEl('#quickEditLayout').onclick=()=>seatEl('#editDeskLayout').click();seatingRoster.addEventListener('input',updateRosterCount)}
setupSeatingWorkspace();
const saved=JSON.parse(localStorage.getItem('glnSeatingClasses')||'null');if(saved?.classes?.length){seatingClasses=saved.classes.map(normalize);activeClassId=saved.activeClassId||seatingClasses[0].id}else{const legacy=JSON.parse(localStorage.getItem('glnSeatingChart')||'null'),initial=normalize(legacy||{className:'My Class',roster:defaultRoster});seatingClasses=[initial];activeClassId=initial.id}applyState(seatingClasses.find(c=>c.id===activeClassId)||seatingClasses[0]);
seatingClassSelect.onchange=()=>switchSeatingClass(seatingClassSelect.value);seatEl('#newSeatingClass').onclick=()=>{saveLocal();const item=blankClass(`Class ${seatingClasses.length+1}`);seatingClasses.push(item);manualRoomScale=null;applyState(item);queueSave()};seatEl('#duplicateSeatingClass').onclick=duplicateCurrentClass;seatEl('#useClassLayout').onclick=useAnotherClassLayout;seatEl('#deleteSeatingClass').onclick=()=>{if(seatingClasses.length===1){showToast('Keep at least one class');return}if(!confirm(`Delete ${seatingState.className}?`))return;seatingClasses=seatingClasses.filter(c=>c.id!==activeClassId);manualRoomScale=null;applyState(seatingClasses[0]);queueSave()};
seatEl('#buildSeating').onclick=buildChart;seatEl('#shuffleSeating').onclick=shuffleChart;seatEl('#flipSeating').onclick=()=>{seatingState.flipped=!seatingState.flipped;renderSeatingChart();queueSave()};seatEl('#editDeskLayout').onclick=toggleLayoutEditor;seatEl('#addDesk').onclick=addDesk;seatEl('#deleteDesk').onclick=deleteSelectedDesks;seatEl('#duplicateDesk').onclick=duplicateSelectedDesk;seatEl('#rotateDesk').onclick=rotateSelected;seatEl('#applyDeskSizeAll').onclick=applySelectedSizeToAll;seatEl('#undoDesk').onclick=undoDeskEdit;seatEl('#redoDesk').onclick=redoDeskEdit;seatEl('#makeSeatingGroups').onclick=createGroups;seatEl('#importSeatingRoster').onclick=()=>seatEl('#seatingFileInput').click();seatEl('#seatingFileInput').onchange=e=>{if(e.target.files[0])importRoster(e.target.files[0]);e.target.value=''};seatEl('#downloadSeating').onclick=downloadChart;seatingLocalMode.onclick=()=>setStorage('local');seatingGoogleMode.onclick=()=>setStorage('google');seatingGoogleSignIn.onclick=signInGoogle;seatEl('#seatingFullscreen').onclick=()=>{if(!document.fullscreenElement)seatEl('#seatingPanel').requestFullscreen?.();else document.exitFullscreen?.()};seatEl('#printSeating').onclick=()=>{document.body.classList.add('print-seating');window.print()};window.addEventListener('afterprint',()=>document.body.classList.remove('print-seating'));[seatingClassName,seatingRoster,seatEl('#seatingKeepApart'),seatEl('#seatingNearFront'),seatEl('#seatingGroupA'),seatEl('#seatingGroupB')].forEach(input=>input.addEventListener('change',queueSave));seatEl('#seatingAlternateGender').onchange=queueSave;setStorage(seatingStorageMode);window.renderSeatingChart=renderSeatingChart;
seatEl('#roomPreset').onchange=setRoomPreset;seatEl('#roomWidth').onchange=updateRoomInputs;seatEl('#roomHeight').onchange=updateRoomInputs;seatEl('#roomResizeHandle').onpointerdown=beginRoomResize;[seatEl('#snapDesks'),seatEl('#smartGuides')].forEach(input=>input.onchange=queueSave);seatEl('#showDeskShortcuts').onclick=()=>seatEl('#deskShortcutDialog').showModal();document.addEventListener('keydown',seatingShortcut);document.addEventListener('fullscreenchange',()=>requestAnimationFrame(updateRoomScale));window.addEventListener('resize',()=>requestAnimationFrame(updateRoomScale));setupShortcutDialog();setupDeskTooltips();

