const originalMoveDeskGroup=moveDeskGroup;
moveDeskGroup=(origins,dx,dy,disableGuides=false)=>{const snapToggle=seatEl('#snapDesks'),wasSnapping=snapToggle.checked;if(wasSnapping)snapToggle.checked=false;try{return originalMoveDeskGroup(origins,disableGuides?dx:Math.round(dx/2)*2,disableGuides?dy:Math.round(dy/2)*2,disableGuides)}finally{snapToggle.checked=wasSnapping}};

