rotateSelected=(direction=1,precision=false)=>{const indexes=selectedDeskIndexes();if(!indexes.length){showToast('Select a desk first');return}const step=precision?1:15,changes=new Map(indexes.map(index=>{const desk=seatingState.deskLayout[index],rotation=((((desk.rotation||0)+direction*step)%360)+360)%360;return[desk.id,{...desk,rotation}]}));if(!validDeskChanges(changes)){flashDeskCollision();showToast('Not enough space to rotate these desks');return}pushDeskHistory();applyDeskChanges(changes);renderSeatingChart();queueSave()};
