document.addEventListener('keydown',event=>{if(seatEl('#seatingPanel').hidden||!layoutEditing)return;const target=event.target;if(/INPUT|TEXTAREA|SELECT/.test(target.tagName)||target.isContentEditable)return;if(event.code==='BracketRight'){event.preventDefault();rotateSelected(1,event.shiftKey)}else if(event.code==='BracketLeft'){event.preventDefault();rotateSelected(-1,event.shiftKey)}else return;event.stopImmediatePropagation()},{capture:true});

// Keep existing students attached to their chosen desks when the roster changes.
buildChart=()=>{capture();if(seatingState.layoutMode!=='custom')return;pushDeskHistory();const remaining=[...seatingState.roster],preserved=seatingState.deskLayout.map((_,index)=>{const current=seatingState.seats[index],match=remaining.indexOf(current);if(current&&match>=0){remaining.splice(match,1);return current}return null});while(preserved.length<seatingState.deskLayout.length)preserved.push(null);while(remaining.length>preserved.filter(name=>!name).length){const index=seatingState.deskLayout.length;let spot=findOpenDeskSpot(98,68);while(!spot&&seatingState.roomHeight<1400){seatingState.roomHeight=Math.min(1400,seatingState.roomHeight+100);spot=findOpenDeskSpot(98,68)}if(!spot){showToast('Room is full — enlarge it to add more desks');break}seatingState.deskLayout.push({id:`desk-${Date.now()}-${index}`,...spot,w:98,h:68,rotation:0});seatingState.locked.push(false);preserved.push(null)}for(let index=0;index<preserved.length&&remaining.length;index++)if(!preserved[index])preserved[index]=remaining.shift();seatingState.seats=preserved;while(seatingState.locked.length<seatingState.deskLayout.length)seatingState.locked.push(false);seatEl('#roomHeight').value=Math.round(seatingState.roomHeight);renderSeatingChart();queueSave();showToast('Names updated — desk assignments preserved')};
seatEl('#buildSeating').onclick=buildChart;
